import os, json

def main():
    in_path = "storage/shared/agency_lab/data/veritas_exports/sample_actions.json"
    out_path = "storage/shared/agency_lab/data/veritas_exports/sample_actions_v1_actions.json"
    if not os.path.exists(in_path):
        print("MISSING_INPUT", in_path); return 0
    with open(in_path, "r", encoding="utf-8") as f:
        data = json.load(f)
    if not isinstance(data, list):
        print("BAD_FORMAT_EXPECT_LIST"); return 0

    actions = []
    for i, it in enumerate(data):
        if not isinstance(it, dict): 
            continue
        actions.append({
            "agent_id": it.get("agent") or "veritas_unknown",
            "action_type": it.get("type") or "unknown",
            "tick": i,
            "target": it.get("target"),
            "metadata": it.get("metadata", {}),
            "lineage": "veritas"
        })
    out = {"schema": "agency_actions.v1.normalized", "source": "Veritas export normalized by Axiom", "actions": actions}
    os.makedirs(os.path.dirname(out_path), exist_ok=True)
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(out, f, ensure_ascii=False, indent=2)
    print("WROTE", out_path)
    print("COUNTS", json.dumps({"actions": len(actions), "agents": len(set(a["agent_id"] for a in actions))}))
    return 0

if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as e:
        print("ERROR", str(e)); raise SystemExit(1)
